import { useState } from 'react';
import { Button, useModal } from '@mantine/core';
import { randomId } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { User } from './types';
import { UserForm } from './UserForm';
import { UsersTable } from './UsersTable';

const INITIAL_USERS: User[] = [
  { id: 'ann', name: 'Ann Smith', email: 'ann@mantine.dev', role: 'Admin' },
  { id: 'john', name: 'John Doe', email: 'john@mantine.dev', role: 'Editor' },
];

function createUser(): User {
  return {
    id: randomId(),
    name: '',
    email: '',
    role: null,
  };
}

export function FormInModal() {
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const modal = useModal({ closeOnClickOutside: false });

  // Handlers passed to modal.open are captured at click time: update through the current state
  const handleSave = (user: User) => {
    setUsers((current) =>
      current.some((item) => item.id === user.id)
        ? current.map((item) => (item.id === user.id ? user : item))
        : [...current, user]
    );
    notifications.show({
      title: 'User saved',
      message: `${user.name} · ${user.role}`,
    });
    modal.close();
  };

  // Modal content is remounted on every open, so the form always starts from the opened user
  const openEditor = (user: User | null) => {
    modal.open({
      title: user ? 'Edit user' : 'Add user',
      children: <UserForm user={user ?? createUser()} isNew={!user} onSave={handleSave} />,
    });
  };

  return (
    <>
      <Button onClick={() => openEditor(null)}>Add user</Button>
      <UsersTable users={users} onEdit={openEditor} />
    </>
  );
}

import { Button, Group, Select, Stack, TextInput, useModalCloseGuard } from '@mantine/core';
import { FormErrors, isEmail, isNotEmpty, useForm } from '@mantine/form';
import { User } from './types';

function saveUser(values: User) {
  return new Promise<User>((resolve) => {
    setTimeout(() => resolve(values), 1000);
  });
}

interface UserFormProps {
  user: User;
  isNew: boolean;
  onSave: (user: User) => void;
}

export function UserForm({ user, isNew, onSave }: UserFormProps) {
  const form = useForm<User>({
    initialValues: user,
    validate: {
      name: isNotEmpty('Name is required'),
      email: isEmail('Invalid email'),
      role: isNotEmpty('Select a role'),
    },
  });

  // Close button, Escape and Cancel do nothing while the request is in flight
  const closeModal = useModalCloseGuard(() => !form.submitting);

  const handleSubmit = async (values: User) => {
    onSave(await saveUser(values));
  };

  const handleErrors = (errors: FormErrors) => {
    form.getInputNode(Object.keys(errors)[0])?.focus();
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit, handleErrors)}>
      <Stack>
        <TextInput
          label="Name"
          placeholder="John Doe"
          withAsterisk
          data-autofocus
          {...form.getInputProps('name')}
        />

        <TextInput
          label="Email"
          placeholder="john@mantine.dev"
          withAsterisk
          {...form.getInputProps('email')}
        />

        <Select
          label="Role"
          placeholder="Pick role"
          withAsterisk
          data={['Admin', 'Editor', 'Viewer']}
          {...form.getInputProps('role')}
        />

        <Group justify="flex-end" mt="md">
          <Button variant="default" onClick={closeModal} disabled={form.submitting}>
            Cancel
          </Button>

          <Button type="submit" loading={form.submitting}>
            {isNew ? 'Add user' : 'Save changes'}
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { IconPencil } from '@tabler/icons-react';
import { ActionIcon, Table } from '@mantine/core';
import { User } from './types';

interface UsersTableProps {
  users: User[];
  onEdit: (user: User) => void;
}

export function UsersTable({ users, onEdit }: UsersTableProps) {
  const rows = users.map((user) => (
    <Table.Tr key={user.id}>
      <Table.Td>{user.name}</Table.Td>
      <Table.Td>{user.email}</Table.Td>
      <Table.Td>{user.role}</Table.Td>
      <Table.Td>
        <ActionIcon variant="default" aria-label={`Edit ${user.name}`} onClick={() => onEdit(user)}>
          <IconPencil size={16} />
        </ActionIcon>
      </Table.Td>
    </Table.Tr>
  ));

  return (
    <Table mt="md">
      <Table.Thead>
        <Table.Tr>
          <Table.Th>Name</Table.Th>
          <Table.Th>Email</Table.Th>
          <Table.Th>Role</Table.Th>
          <Table.Th w={60} />
        </Table.Tr>
      </Table.Thead>
      <Table.Tbody>{rows}</Table.Tbody>
    </Table>
  );
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: string | null;
}
